default.shell:
$mismatchCount = 0

$service = Get-Service -Name 'lfsvc' -ErrorAction SilentlyContinue
if ($service) {
    if ($service.StartType -ne 'Disabled') {
        Write-Output ('Mismatch: service lfsvc start type is ' + $service.StartType + ', expected Disabled')
        $mismatchCount++
    }
    if ($service.Status -ne 'Stopped') {
        Write-Output ('Mismatch: service lfsvc is ' + $service.Status + ', expected Stopped')
        $mismatchCount++
    }
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

$service = Get-Service -Name 'lfsvc' -ErrorAction SilentlyContinue
if ($service) {
    Set-Service -Name 'lfsvc' -StartupType Disabled
    if ($service.Status -ne 'Stopped') {
        Stop-Service -Name 'lfsvc'
    }
}

exit 0
